-- Catalog: quest items and keepsakes (untradeable, kept on death, never sold).
insert into eldervale_private.realm_catalog(id,data) select r->>0,r->1 from jsonb_array_elements($j$[["item:custom_qa_forged_writ",{"name":"Forged royal writ","description":"A grain writ with the Queen’s seal: crisp, perfect and false. Odo Penwhistle gave it to you as evidence.","icon":"scroll","custom":true,"category":"Quest items","buy":0,"sell":0,"unique":true,"tradeable":false,"untradeable":true,"questItem":true,"keepOnDeath":true,"shopless":true}],["item:custom_qa_wax_ledger",{"name":"Wax-stained ledger","description":"A forger’s book of commissions, its pages sealed with drips of tallow. Someone paid a great deal for silence.","icon":"scroll","custom":true,"category":"Quest items","buy":0,"sell":0,"unique":true,"tradeable":false,"untradeable":true,"questItem":true,"keepOnDeath":true,"shopless":true}],["item:custom_qa_varrow_crown",{"name":"Melted Varrow crown","description":"The old crown of House Varrow, slumped by the heat of its last wearer. Captain Varn will want it.","icon":"gem","custom":true,"category":"Quest items","buy":0,"sell":0,"unique":true,"tradeable":false,"untradeable":true,"questItem":true,"keepOnDeath":true,"shopless":true}],["item:custom_qa_tallow_signet",{"name":"Signet of the Lamplit Court","description":"A small gold signet stamped with a candle flame. Rub it to return to Crown Court in Birchford.","icon":"gem","custom":true,"category":"Quest items","buy":0,"sell":0,"unique":true,"tradeable":false,"untradeable":true,"questItem":true,"keepOnDeath":true,"shopless":true}]]$j$::jsonb) r
on conflict(id) do update set data=excluded.data where not coalesce((eldervale_private.realm_catalog.data->>'ownerEdited')::boolean,false) and eldervale_private.realm_catalog.data is distinct from excluded.data;

-- People, monsters and shortcuts of the arc (fixed ids; the entity trigger fills realm_actors / realm_objects).
select eldervale_private.quest_arc_entities($j$[{"id":"a3c0a000-0001-4000-8000-000000000001","data":{"kind":"npc","name":"Odo Penwhistle","role":"resident","weapon":null,"attackType":"punch","color":8356955,"level":5,"hp":45,"damage":4,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"Under-Clerk of the Chancery. Nine ledgers, eleven pens, and not one honest minute to myself.","template":"villager","x":-214.4,"z":136,"yaw":180,"questArc":"crown","blueprint":"quest-arcs-v1","blueprintKey":"crown:odo"}},{"id":"a3c0a000-0001-4000-8000-000000000002","data":{"kind":"npc","name":"Marta Kell the Sealwright","role":"merchant","weapon":"dagger","attackType":"stab","color":10253389,"level":5,"hp":45,"damage":4,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"Seals, signets, wax and ribbon.\nA good seal is a promise you can hold in your hand.","template":"merchant","x":-191,"z":159.5,"yaw":0,"questArc":"crown","blueprint":"quest-arcs-v1","blueprintKey":"crown:marta"}},{"id":"a3c0a000-0001-4000-8000-000000000003","data":{"kind":"npc","name":"Fenn Dunlow","role":"resident","weapon":null,"attackType":"punch","color":8356955,"level":5,"hp":45,"damage":4,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"Dunlow’s Chandlery. Twice-rendered tallow, smokeless, nearly.","template":"villager","x":-197,"z":147,"yaw":90,"questArc":"crown","blueprint":"quest-arcs-v1","blueprintKey":"crown:fenn"}},{"id":"a3c0a000-0001-4000-8000-000000000004","data":{"kind":"npc","name":"Captain Isolde Varn","role":"guard","weapon":"twohand","attackType":"slash","color":5466234,"level":35,"hp":180,"damage":19,"attackSpeed":3.2,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"The Keep Watch serves the Queen, not the Queen’s favourites.\nMind the court; it has ears.","template":"knight","x":-229,"z":168,"yaw":-90,"questArc":"crown","blueprint":"quest-arcs-v1","blueprintKey":"crown:varn"}},{"id":"a3c0a000-0001-4000-8000-000000000005","data":{"kind":"npc","name":"Lady Merrow Ashgrove","role":"mage","weapon":null,"attackType":"magic","color":6312331,"level":18,"hp":65,"damage":13,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"Mistress of Ceremonies to Her Majesty.\nEvery feast is a little war, darling. I simply win them.","template":"mage","x":-235.5,"z":174,"yaw":90,"questArc":"crown","blueprint":"quest-arcs-v1","blueprintKey":"crown:merrow"}},{"id":"a3c0a000-0001-4000-8000-000000000006","data":{"kind":"npc","name":"Old Sable","role":"resident","weapon":null,"attackType":"punch","color":8356955,"level":5,"hp":45,"damage":4,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"My eyes went years ago. My fingers still read paper better than yours.","template":"villager","x":-152,"z":136.5,"yaw":-90,"questArc":"crown","blueprint":"quest-arcs-v1","blueprintKey":"crown:sable"}},{"id":"a3c0a000-0001-4000-8000-000000000007","data":{"kind":"npc","name":"Ivy Sable","role":"resident","weapon":null,"attackType":"punch","color":8356955,"level":5,"hp":45,"damage":4,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"I mend letters for people who cannot write. That is all I do now.","template":"villager","x":-209,"z":184,"yaw":180,"questArc":"crown","blueprint":"quest-arcs-v1","blueprintKey":"crown:ivy"}},{"id":"a3c0a000-0001-4000-8000-000000000008","data":{"kind":"npc","name":"Lady Merrow Ashgrove","role":"mage","weapon":null,"attackType":"magic","color":6312331,"level":18,"hp":65,"damage":13,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"The wax is cooling. So is everything I built.","template":"mage","x":1462,"z":3006,"yaw":-90,"questArc":"crown","blueprint":"quest-arcs-v1","blueprintKey":"crown:merrow_vault"}},{"id":"a3c0a000-0001-4000-8000-000000000009","data":{"kind":"npc","name":"Royal Quartermaster Bede","role":"merchant","weapon":"dagger","attackType":"stab","color":10253389,"level":5,"hp":45,"damage":4,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"The Treasury Arcade serves friends of the Crown.\nThe prices are fair. The company is better.","template":"merchant","x":1422,"z":3404,"yaw":180,"questArc":"crown","blueprint":"quest-arcs-v1","blueprintKey":"crown:quartermaster","shop":{"adamantBar":{"buy":960,"sell":290,"stock":20},"runiteBar":{"buy":3200,"sell":960,"stock":6},"healingPotion":{"buy":180,"sell":50,"stock":30},"steelArrows":{"buy":12,"sell":3,"stock":500},"silverBar":{"buy":150,"sell":45,"stock":30}}}},{"id":"a3c0a000-0001-4000-8000-00000000000a","data":{"kind":"npc","name":"Hobb Wainright the Drover","role":"farmer","weapon":"axe","attackType":"slash","color":10189901,"level":5,"hp":45,"damage":4,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"Oxen, carts and grain. Ask me about any of the three. Not the weather.","template":"farmer","x":-282,"z":150,"yaw":90,"questArc":"crown","blueprint":"quest-arcs-v1","blueprintKey":"crown:hobb"}},{"id":"a3c0a000-0001-4000-9000-000000000001","data":{"kind":"monster","name":"Gutter-Jack","species":"human","attackType":"stab","level":16,"hp":220,"damage":3,"attackSpeed":2.6,"roam":2,"respawn":60,"attackable":true,"hostile":true,"scale":1,"weapon":"dagger","template":"bandit","x":-128,"z":142,"yaw":0,"maxHit":32,"attackLevel":16,"strengthLevel":13,"defenceLevel":11,"magicLevel":5,"attackBonus":5,"defenceBonuses":{"stab":4,"slash":4,"crush":5,"magic":4,"ranged":4},"xpReward":154,"goldReward":30,"look":{"skin":"#b98262","hair":"Cropped","hairColor":"#3a2a1d","beard":"Beard"},"gear":["peasantShirt3","peasantTrousers3","rangerHood3"],"examine":"He smells of lime and lies.","loot":[{"item":"custom_qa_wax_ledger","min":1,"max":1,"chance":1,"always":true},{"item":"bones","min":1,"max":1,"chance":1,"always":true}],"behavior":"wander","questArc":"crown","blueprint":"quest-arcs-v1","blueprintKey":"crown:jack"}},{"id":"a3c0a000-0001-4000-9000-000000000002","data":{"kind":"monster","name":"Varrow cutthroat","species":"human","attackType":"slash","level":24,"hp":245,"damage":3,"attackSpeed":2.6,"roam":2,"respawn":60,"attackable":true,"hostile":true,"scale":1,"weapon":"steelScimitar","template":"bandit","x":-298,"z":134,"yaw":0,"maxHit":39,"attackLevel":24,"strengthLevel":19,"defenceLevel":17,"magicLevel":7,"attackBonus":8,"defenceBonuses":{"stab":6,"slash":6,"crush":7,"magic":6,"ranged":6},"xpReward":298,"goldReward":50,"look":{"skin":"#c69a7a","hair":"Long","hairColor":"#5b3c28","beard":"Beard"},"gear":["knightGambeson2","peasantTrousers2","knightScarf2"],"examine":"An old crown is stitched inside his collar.","loot":[{"item":"bones","min":1,"max":1,"chance":1,"always":true}],"behavior":"wander","questArc":"crown","blueprint":"quest-arcs-v1","blueprintKey":"crown:cutthroat1"}},{"id":"a3c0a000-0001-4000-9000-000000000003","data":{"kind":"monster","name":"Varrow cutthroat","species":"human","attackType":"slash","level":24,"hp":245,"damage":3,"attackSpeed":2.6,"roam":2,"respawn":60,"attackable":true,"hostile":true,"scale":1,"weapon":"steelScimitar","template":"bandit","x":-302,"z":140,"yaw":0,"maxHit":39,"attackLevel":24,"strengthLevel":19,"defenceLevel":17,"magicLevel":7,"attackBonus":8,"defenceBonuses":{"stab":6,"slash":6,"crush":7,"magic":6,"ranged":6},"xpReward":298,"goldReward":50,"look":{"skin":"#c69a7a","hair":"Long","hairColor":"#5b3c28","beard":"Beard"},"gear":["knightGambeson2","peasantTrousers2","knightScarf2"],"examine":"An old crown is stitched inside his collar.","loot":[{"item":"bones","min":1,"max":1,"chance":1,"always":true}],"behavior":"wander","questArc":"crown","blueprint":"quest-arcs-v1","blueprintKey":"crown:cutthroat2"}},{"id":"a3c0a000-0001-4000-9000-000000000004","data":{"kind":"monster","name":"Varrow cutthroat","species":"human","attackType":"slash","level":24,"hp":245,"damage":3,"attackSpeed":2.6,"roam":2,"respawn":60,"attackable":true,"hostile":true,"scale":1,"weapon":"steelScimitar","template":"bandit","x":-296,"z":145,"yaw":0,"maxHit":39,"attackLevel":24,"strengthLevel":19,"defenceLevel":17,"magicLevel":7,"attackBonus":8,"defenceBonuses":{"stab":6,"slash":6,"crush":7,"magic":6,"ranged":6},"xpReward":298,"goldReward":50,"look":{"skin":"#c69a7a","hair":"Long","hairColor":"#5b3c28","beard":"Beard"},"gear":["knightGambeson2","peasantTrousers2","knightScarf2"],"examine":"An old crown is stitched inside his collar.","loot":[{"item":"bones","min":1,"max":1,"chance":1,"always":true}],"behavior":"wander","questArc":"crown","blueprint":"quest-arcs-v1","blueprintKey":"crown:cutthroat3"}},{"id":"a3c0a000-0001-4000-9000-000000000005","data":{"kind":"monster","name":"Tallow sentry","species":"golem","attackType":"slam","level":48,"hp":580,"damage":6,"attackSpeed":4,"roam":1,"respawn":45,"attackable":true,"hostile":true,"scale":1.3,"template":"golem","x":1424,"z":2997,"yaw":0,"maxHit":73,"attackLevel":41,"strengthLevel":48,"defenceLevel":60,"magicLevel":19,"attackBonus":16,"defenceBonuses":{"stab":22,"slash":24,"crush":8,"magic":18,"ranged":26},"xpReward":998,"goldReward":130,"tint":15260072,"eyes":16765562,"accent":16757575,"examine":"A guardsman made of candle-ends. It drips when it marches.","loot":[{"item":"coal","min":2,"max":5,"chance":1,"always":true}],"behavior":"wander","questArc":"crown","blueprint":"quest-arcs-v1","blueprintKey":"crown:sentry1"}},{"id":"a3c0a000-0001-4000-9000-000000000006","data":{"kind":"monster","name":"Tallow sentry","species":"golem","attackType":"slam","level":48,"hp":580,"damage":6,"attackSpeed":4,"roam":1,"respawn":45,"attackable":true,"hostile":true,"scale":1.3,"template":"golem","x":1426,"z":3004,"yaw":0,"maxHit":73,"attackLevel":41,"strengthLevel":48,"defenceLevel":60,"magicLevel":19,"attackBonus":16,"defenceBonuses":{"stab":22,"slash":24,"crush":8,"magic":18,"ranged":26},"xpReward":998,"goldReward":130,"tint":15260072,"eyes":16765562,"accent":16757575,"examine":"A guardsman made of candle-ends. It drips when it marches.","loot":[{"item":"coal","min":2,"max":5,"chance":1,"always":true}],"behavior":"wander","questArc":"crown","blueprint":"quest-arcs-v1","blueprintKey":"crown:sentry2"}},{"id":"a3c0a000-0001-4000-9000-000000000007","data":{"kind":"monster","name":"The Tallow Regent","species":"golem","attackType":"slam","level":86,"hp":2575,"damage":14,"attackSpeed":4,"roam":1,"respawn":90,"attackable":true,"hostile":true,"scale":2.3,"template":"golem","x":1452,"z":3000,"yaw":0,"maxHit":175,"attackLevel":79,"strengthLevel":93,"defenceLevel":116,"magicLevel":37,"attackBonus":39,"defenceBonuses":{"stab":39,"slash":42,"crush":14,"magic":31,"ranged":45},"xpReward":5521,"goldReward":684,"tint":15852470,"eyes":16769162,"accent":16760906,"examine":"A king of wax, crowned in a crown that outlived its kingdom.","loot":[{"item":"custom_qa_varrow_crown","min":1,"max":1,"chance":1,"always":true},{"item":"coal","min":2,"max":5,"chance":1,"always":true}],"behavior":"wander","questArc":"crown","blueprint":"quest-arcs-v1","blueprintKey":"crown:regent","aura":16760906,"crown":true}},{"id":"a3c0a000-0001-4000-9000-000000000008","data":{"kind":"monster","name":"The Gilded Regent","species":"golem","attackType":"slam","level":108,"hp":4010,"damage":19,"attackSpeed":3.8,"roam":1,"respawn":300,"attackable":true,"hostile":true,"scale":2.6,"template":"golem","x":1446,"z":3400,"yaw":0,"maxHit":237,"attackLevel":99,"strengthLevel":117,"defenceLevel":146,"magicLevel":47,"attackBonus":50,"defenceBonuses":{"stab":50,"slash":54,"crush":18,"magic":40,"ranged":58},"xpReward":8597,"goldReward":1037,"tint":14267466,"eyes":16773544,"accent":16765514,"examine":"The Regent, recast in gold leaf by someone who should have known better. Harder mode.","loot":[{"item":"runiteBar","min":1,"max":3,"chance":0.4},{"item":"goldBar","min":3,"max":8,"chance":1,"always":true},{"item":"cutGem","min":1,"max":3,"chance":0.5},{"item":"coal","min":2,"max":5,"chance":1,"always":true}],"behavior":"wander","questArc":"crown","blueprint":"quest-arcs-v1","blueprintKey":"crown:gilded","aura":16769658,"crown":true}},{"id":"a3c0a000-0001-4000-a000-000000000001","data":{"kind":"object","name":"Sable’s Old Climb","scale":1,"level":1,"hp":1,"damage":0,"attackSpeed":2.4,"roam":0,"respawn":0,"attackable":false,"hostile":false,"template":"wall_climb","x":-212,"z":79.9,"yaw":180,"length":7.4,"agility":{"id":"sables_climb","level":18,"xp":16,"fail":0.15,"failDamage":25,"ticks":4,"margin":20,"ends":[[-212,83.6],[-212,76.2]],"requires":{"unlock":"shortcut.crown-sables-climb"}},"questArc":"crown","blueprint":"quest-arcs-v1","blueprintKey":"crown:sables_climb"}}]$j$::jsonb);

-- Quests (validated by quest_v2_check; edit them later in the Game console › Quests).
select eldervale_private.quest_arc_put('a3c0b000-0001-4000-8000-000000000001',$q${"chain":"arc-crown","order":1,"published":true,"objectives":[],"key":"arc-crown-1","name":"Wax and Whispers","questPoints":1,"difficulty":"Novice","length":"Short","giver":"a3c0a000-0001-4000-8000-000000000001","icon":"custom_qa_forged_writ","description":"Under-Clerk Odo Penwhistle has found royal grain writs bearing the Queen’s seal that the Queen never signed. He would like someone without a reputation to lose to ask a few questions.","startItems":{"custom_qa_forged_writ":1},"dialogue":{"offer":[{"who":"npc","text":"Psst. You. Yes, you, the one without a quill behind your ear."},{"who":"npc","text":"Three writs came through the Chancery this week ordering royal grain carted out of the Frost Gate. Each one wears Her Majesty’s seal."},{"who":"npc","text":"Her Majesty was in bed with a fever all week. She sealed nothing but her own soup."},{"who":"player","text":"So someone forged her seal?"},{"who":"npc","text":"Someone forged it beautifully. Take this one to Marta Kell, the sealwright in the Grand Market. If anyone can tell how it was done, she can."}],"progress":[{"who":"npc","text":"Any news? I have started sealing my lunch, just in case."}],"complete":[{"who":"npc","text":"A cast seal, a chandler’s boy, and coins of a house that died before I was born. Oh, I do not like this at all."},{"who":"npc","text":"Thank you. Captain Varn has the matter now, which means I can go back to being ignored. Bliss."}]},"branchDialogue":[{"stage":"complete","ifFlags":{"fenn_informant":true},"lines":[{"who":"npc","text":"So the boy keeps his apron and you keep an ear in the market. Clever. I shall pretend I did not hear that."},{"who":"npc","text":"Captain Varn has the writs now. Thank you, truly."}]}],"stages":[{"id":"sealwright","journal":"Odo Penwhistle, Under-Clerk of the Chancery, showed me grain writs sealed in the Queen’s name while she lay sick. He asked me to show one to Marta Kell, the sealwright in the Grand Market.","objectives":[{"type":"talk","target":"a3c0a000-0001-4000-8000-000000000002","amount":1,"label":"Show the forged writ to Marta Kell in the Grand Market","dialogue":[{"who":"npc","text":"Let me see. Hm. Hmmm. Too crisp."},{"who":"npc","text":"A seal pressed by hand blurs at the rim. This one is sharp as a coin: it was cast in a mould, then warmed on."},{"who":"npc","text":"A mould needs fine wax that holds an edge. Twice-rendered tallow. Only Dunlow’s Chandlery renders it twice, off Market Lane."}]}]},{"id":"chandlery","journal":"Marta said the seal was cast from a mould of twice-rendered tallow, which only Dunlow’s Chandlery makes. I should look around the chandlery yard at the end of Market Lane before anyone tidies it.","objectives":[{"type":"visit","x":-197.5,"z":152.5,"radius":3,"amount":1,"label":"Search the chandlery yard at the end of Market Lane"}]},{"id":"boy","journal":"Among the tallow barrels I found broken plaster moulds still smelling of the Queen’s seal-wax. The chandler’s boy, Fenn Dunlow, was watching me from the doorway.","npc":"a3c0a000-0001-4000-8000-000000000003","onEnter":{"cutscene":"moulds"},"objectives":[{"type":"talk","target":"a3c0a000-0001-4000-8000-000000000003","amount":1,"label":"Talk to Fenn Dunlow","dialogue":[{"who":"npc","text":"Those are just... rubbish. Old moulds. For candles."},{"who":"player","text":"Candles shaped like the Queen’s seal?"},{"who":"npc","text":"...Fine! A veiled lady paid me to cast them. She paid in these. Old coins, heavy ones, with a crown nobody uses any more."}]}],"dialogue":{"choice":[{"who":"npc","text":"Please. If the Watch takes me, my father loses the shop. I did not know what they were for, I swear on my wick."}]},"choices":[{"id":"report","label":"I’m sorry, Fenn. The Watch has to hear this from you.","flags":{"reported_fenn":true},"dialogue":[{"who":"npc","text":"...All right. I will tell them everything. I hope she was worth it, whoever she is."}]},{"id":"informant","label":"Keep your apron on. You’ll be my eyes in the market instead.","flags":{"fenn_informant":true},"dialogue":[{"who":"npc","text":"Your eyes? I can do that. I see everything from the dipping vats. Everything."}]}]},{"id":"captain","journal":"Fenn admitted casting the moulds for a veiled lady who paid in old crowns of House Varrow, the family that lost the throne two generations ago. Odo will want the Keep Watch told, and he has asked for two honest candles so he can seal his own reports properly from now on.","objectives":[{"type":"talk","target":"a3c0a000-0001-4000-8000-000000000004","amount":1,"label":"Tell Captain Isolde Varn at Crown Court","dialogue":[{"who":"npc","text":"Varrow crowns? Those were melted down after the Long Dusk. All of them. Supposedly."},{"who":"npc","text":"I will put a quiet watch on the Frost Gate carts. Tell Odo he did right to whisper."}]},{"type":"collect","target":"candle","amount":2,"label":"Bring Odo two honest candles"}]}],"cutscenes":{"moulds":{"name":"The broken moulds","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0001-4000-8000-000000000003","distance":5,"height":2.2,"angle":30}},{"title":"Dunlow’s Chandlery","subtitle":"Market Lane, Birchford","ms":2400},{"say":{"who":"npc","name":"Fenn Dunlow","text":"Oh. You found those. I was going to bury them. Honestly. Today. Probably."},"shot":{"around":"a3c0a000-0001-4000-8000-000000000003","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"writs":{"name":"Out of the Frost Gate","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0001-4000-8000-000000000004","distance":5,"height":2.2,"angle":30}},{"title":"A quiet watch","subtitle":"Crown Court, Birchford","ms":2400},{"say":{"who":"npc","name":"Captain Isolde Varn","text":"Whoever paid in Varrow coin wants the old house remembered. I would rather know why before the whole city does."},"shot":{"around":"a3c0a000-0001-4000-8000-000000000004","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]}},"onComplete":{"cutscene":"writs"},"journalDone":"I traced the Queen’s forged seal to wax moulds cast at Dunlow’s Chandlery and paid for in coins of the fallen House Varrow. Captain Varn of the Keep Watch is watching the Frost Gate carts.","journalVariants":[{"ifFlags":{"reported_fenn":true},"text":"Fenn Dunlow confessed to the Watch."},{"ifFlags":{"fenn_informant":true},"text":"Fenn Dunlow kept his apron and now listens in the market for me."}],"gold":150,"xp":{"crafting":1500,"thieving":800},"lamps":[{"perLevel":10,"minLevel":5,"label":"Chancery lamp"}],"unlocks":[{"type":"flag","id":"crown.varrow_coin_found","label":"Birchford whispers about Varrow coin"},{"type":"dialogue","id":"dialogue.crown-odo-1","label":"Odo trusts you","npc":"a3c0a000-0001-4000-8000-000000000001","lines":[{"who":"npc","text":"My honest candles burn beautifully. I seal everything now. Everything. My landlady is alarmed."}]},{"type":"dialogue","id":"dialogue.crown-fenn-report","label":"Fenn remembers the Watch","npc":"a3c0a000-0001-4000-8000-000000000003","ifFlags":{"reported_fenn":true},"lines":[{"who":"npc","text":"The Watch let me off with a fine and a lecture. The lecture was worse."}]},{"type":"dialogue","id":"dialogue.crown-fenn-eyes","label":"Fenn, your eyes in the market","npc":"a3c0a000-0001-4000-8000-000000000003","ifFlags":{"fenn_informant":true},"lines":[{"who":"npc","text":"Nothing new at the vats. Well. A man bought nine candles and cried. Unrelated, I think."}]}]}$q$::jsonb);
select eldervale_private.quest_arc_put('a3c0b000-0001-4000-8000-000000000002',$q${"chain":"arc-crown","order":2,"published":true,"objectives":[],"key":"arc-crown-2","name":"The Forger’s Hand","questPoints":2,"difficulty":"Intermediate","length":"Medium","giver":"a3c0a000-0001-4000-8000-000000000004","icon":"custom_qa_wax_ledger","requirements":{"quests":["arc-crown-1"],"skills":{"cooking":{"level":15,"boostable":false}}},"description":"Captain Varn knows of one man who could have taught anyone to forge a royal seal: Old Sable, who lives outside the Ember Gate and swears he has retired.","dialogue":{"offer":[{"who":"npc","text":"Only one forger in living memory could fool the Chancery. Old Sable. He forged the pardon that ended the Long Dusk, and the Crown has paid his rent ever since to keep his hands still."},{"who":"npc","text":"He lives in a lime-washed hut past the Ember Gate. He hates the Watch. He might not hate you."},{"who":"player","text":"I’ll pay him a visit."},{"who":"npc","text":"Mind his temper. And his teeth. He still has three."}],"progress":[{"who":"npc","text":"Well? Did Sable bite?"}],"complete":[{"who":"npc","text":"A ledger of every seal that was forged, and who paid. That is a noose woven out of ink."},{"who":"npc","text":"You have done the Crown a real service. Take this, and do not spend it on candles."}]},"branchDialogue":[{"stage":"complete","ifFlags":{"spared_ivy":true},"lines":[{"who":"npc","text":"One page has been torn out of this ledger. Neatly, too."},{"who":"npc","text":"I will not ask. I suspect I would not like either answer. Thank you, all the same."}]}],"stages":[{"id":"sable","journal":"Captain Varn sent me to Old Sable, the retired forger who lives in a hut past the Ember Gate. The Crown pays his rent to keep his hands still.","npc":"a3c0a000-0001-4000-8000-000000000006","objectives":[{"type":"talk","target":"a3c0a000-0001-4000-8000-000000000006","amount":1,"label":"Find Old Sable past the Ember Gate","dialogue":[{"who":"npc","text":"Footsteps like a clerk and a sword-belt that squeaks. Watch business?"},{"who":"player","text":"Someone is forging the Queen’s seal. Cast seals, Varrow coin."},{"who":"npc","text":"Cast seals. Clumsy. I am blind, friend, so it was not me."},{"who":"npc","text":"But I will feel the work, if you feed me first. Nobody has brought me a hot supper since the old king died."}]}],"dialogue":{"advance":[{"who":"npc","text":"Two trout, cooked properly. Not burnt. I can smell burnt from the river."}]}},{"id":"supper","journal":"Old Sable is blind, so he cannot be the forger, but he offered to read the forged seal with his fingers if I brought him a proper supper: two cooked trout.","npc":"a3c0a000-0001-4000-8000-000000000006","objectives":[{"type":"collect","target":"trout","amount":2,"label":"Bring Old Sable two cooked trout"}],"dialogue":{"advance":[{"who":"npc","text":"Mm. Now, the writ."},{"who":"npc","text":"...Oh. Oh, no. This rim, this little tallow flame hidden in the crest. That is my mark, taught to one pupil only."},{"who":"npc","text":"My pupil keeps a book of every commission. Always did. If it exists, it is in the old lime kiln down the road, and the brute who guards the kiln is called Gutter-Jack."}]}},{"id":"kiln","journal":"Sable recognised a tiny tallow flame hidden in the seal: the mark he taught to a single pupil. That pupil keeps a ledger of commissions in the old lime kiln east along the Emberspire Road, guarded by a thug named Gutter-Jack.","onEnter":{"cutscene":"kiln"},"objectives":[{"type":"kill","target":"a3c0a000-0001-4000-9000-000000000001","amount":1,"label":"Deal with Gutter-Jack at the lime kiln"},{"type":"have","target":"custom_qa_wax_ledger","amount":1,"label":"Take the wax-stained ledger back to Old Sable"}],"npc":"a3c0a000-0001-4000-8000-000000000006","dialogue":{"choice":[{"who":"npc","text":"You have it? Read me the last page. ...No. Read me the name on it."},{"who":"player","text":"“Commissions taken by I. Sable.”"},{"who":"npc","text":"Ivy. My granddaughter. I taught her when she was nine, so she would never need to beg."},{"who":"npc","text":"She would not do this for money. Somebody owns her. Please. Tear the page out. Let me find her before the Watch does."}]},"choices":[{"id":"name","label":"The Captain gets the whole ledger, Ivy’s name included.","flags":{"named_ivy":true},"dialogue":[{"who":"npc","text":"Then the Watch will have her by nightfall. Be kind to her in your report. She was a kind child."}]},{"id":"spare","label":"I’ll tear out her page. Find her first.","flags":{"spared_ivy":true},"dialogue":[{"who":"npc","text":"Thank you. I will not forget this, and neither will she, if I have anything to do with it."}]}]},{"id":"report","journal":"Gutter-Jack is dealt with and I have the forger’s ledger. Its commissions were all taken by Ivy Sable, the old man’s granddaughter. I should take the ledger to Captain Varn at Crown Court.","objectives":[{"type":"collect","target":"custom_qa_wax_ledger","amount":1,"label":"Give the ledger to Captain Varn"}]}],"cutscenes":{"kiln":{"name":"The lime kiln","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0001-4000-8000-000000000006","distance":5,"height":2.2,"angle":30}},{"title":"Kilnside","subtitle":"East of the Ember Gate","ms":2400},{"say":{"who":"npc","name":"Old Sable","text":"Gutter-Jack used to carry my ink. Now he carries a club. Some men only get worse with practice."},"shot":{"around":"a3c0a000-0001-4000-8000-000000000006","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"ledger":{"name":"Ink and a noose","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0001-4000-8000-000000000004","distance":5,"height":2.2,"angle":30}},{"title":"The Forger’s Ledger","subtitle":"Crown Court, Birchford","ms":2400},{"say":{"who":"npc","name":"Captain Isolde Varn","text":"Every payment signed “M.A.”. Whoever M.A. is, they are inside the Keep. That narrows it to about two hundred people."},"shot":{"around":"a3c0a000-0001-4000-8000-000000000004","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]}},"onComplete":{"cutscene":"ledger"},"journalDone":"Old Sable read the forged seal by touch and named the mark of his only pupil. I took the forger’s ledger from Gutter-Jack and gave it to Captain Varn: every commission was paid by someone signing as “M.A.”.","journalVariants":[{"ifFlags":{"named_ivy":true},"text":"I gave the Captain the whole ledger, Ivy Sable’s name included."},{"ifFlags":{"spared_ivy":true},"text":"I tore out Ivy Sable’s page so her grandfather could find her first."}],"gold":400,"xp":{"crafting":6000,"cooking":3000,"agility":2500},"lamps":[{"perLevel":10,"minLevel":10,"label":"Forger’s lamp"}],"unlocks":[{"type":"shortcut","id":"shortcut.crown-sables-climb","label":"Sable’s Old Climb: over the north wall by the bakery (Agility 18)"},{"type":"flag","id":"crown.forgers_ledger","label":"The Watch holds the forger’s ledger"},{"type":"dialogue","id":"dialogue.crown-sable-named","label":"Sable is grieving","npc":"a3c0a000-0001-4000-8000-000000000006","ifFlags":{"named_ivy":true},"lines":[{"who":"npc","text":"They have my Ivy in a cell. She sends word that the bread is stale and the guards are kind. Small mercies."}]},{"type":"dialogue","id":"dialogue.crown-sable-spared","label":"Sable is grateful","npc":"a3c0a000-0001-4000-8000-000000000006","ifFlags":{"spared_ivy":true},"lines":[{"who":"npc","text":"Ivy is safe with me. She will not say who owns her yet. But she is safe."},{"who":"npc","text":"My old climb over the north wall still holds, by the bakery. Use it. I owe you that much."}]}]}$q$::jsonb);

commit;
